"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33896"],{19974(e){e.exports=JSON.parse('{"id":"FIN-409","slug":"ev-revenue","term":"EV/Revenue","also_known_as":[],"difficulty":"Intermediate","definition":"EV/Revenue is a valuation multiple that divides a company\'s enterprise value by its total revenue.","explanation":["EV/Revenue shows how much the whole business, including debt, is valued for each unit of sales. It is the enterprise value equivalent of the price-to-sales ratio.","For example, a company with an enterprise value of 600 million and annual revenue of 200 million has an EV/Revenue multiple of 3.","The multiple is especially useful for companies that are not yet profitable or have negative EBITDA, such as early-stage technology or biotech businesses, where earnings-based multiples cannot be used. It is also used in industries where companies are often compared on sales, such as software.","Because it includes debt, EV/Revenue is better than the price-to-sales ratio for comparing companies with different capital structures.","Its main weakness is that it ignores profitability entirely. Two companies with the same revenue can deserve very different values depending on their profit margins and growth. EV/Revenue multiples should therefore be compared between companies with similar margins and growth prospects, and are usually combined with other measures."],"note":"","total":1500,"prev":{"slug":"ev-ebitda","term":"EV/EBITDA"},"next":{"slug":"ex-dividend-date","term":"Ex-Dividend Date"}}')}}]);